"""Training history (fixed infrastructure - students do not edit this file).

Every training gets its own folder inside ``assets/outputs/trainings/``::

    assets/outputs/trainings/20261112_141846_yolo11n_e50/
      run.json            what was trained (model, epochs, batch, dataset summary, status)
      log.txt             the text log shown in the Train page
      results.csv         per-epoch losses and mAP written by ultralytics
      args.yaml           every ultralytics argument that was used
      weights/best.pt     the fine-tuned model  <- used in Step 3 (Before / After)

Deleting a training = deleting its folder, so results, log and weights always go together.
"""
from __future__ import annotations

import csv
import json
import re
import shutil
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path

from config import TRAININGS_DIR

STATUS_RUNNING = "running"
STATUS_FINISHED = "finished"
STATUS_STOPPED = "stopped"          # the user pressed Stop (the best weights so far are kept)
STATUS_INTERRUPTED = "interrupted"  # the program was closed / crashed during training


class HistoryError(Exception):
    """Raised for problems the user can understand (a folder cannot be deleted, ...)."""


@dataclass
class EpochPoint:
    epoch: int
    train_loss: float | None
    val_loss: float | None
    map50: float | None


@dataclass
class RunRecord:
    run_id: str
    path: Path
    name: str = ""
    created: str = ""
    model: str = ""
    epochs: int = 0
    batch: int = 0
    status: str = STATUS_RUNNING
    duration_sec: float = 0.0
    classes: list[str] = field(default_factory=list)
    train_images: int = 0
    val_images: int = 0

    # ---- files ---------------------------------------------------------- #
    @property
    def weights_path(self) -> Path:
        return self.path / "weights" / "best.pt"

    @property
    def has_weights(self) -> bool:
        return self.weights_path.exists()

    @property
    def log_path(self) -> Path:
        return self.path / "log.txt"

    # ---- results -------------------------------------------------------- #
    def curve(self) -> list[EpochPoint]:
        return read_results_csv(self.path / "results.csv")

    def summary(self) -> dict:
        """Numbers shown in the history table (computed from results.csv)."""
        points = self.curve()
        maps = [p.map50 for p in points if p.map50 is not None]
        last = points[-1] if points else None
        return {
            "epochs_done": len(points),
            "best_map50": max(maps) if maps else None,
            "best_epoch": (maps.index(max(maps)) + 1) if maps else None,
            "final_train_loss": last.train_loss if last else None,
            "final_val_loss": last.val_loss if last else None,
        }

    @property
    def title(self) -> str:
        """Short human-readable name, e.g. '12 Nov 14:18 - yolo11n - 50 epochs'."""
        when = self.created
        try:
            when = datetime.fromisoformat(self.created).strftime("%d %b %H:%M")
        except ValueError:
            pass
        label = f"{when} - {Path(self.model).stem} - {self.epochs} epochs"
        return f"{self.name} ({label})" if self.name else label

    def to_json(self) -> dict:
        return {
            "run_id": self.run_id, "name": self.name, "created": self.created,
            "model": self.model, "epochs": self.epochs, "batch": self.batch,
            "status": self.status, "duration_sec": round(self.duration_sec, 1),
            "classes": self.classes, "train_images": self.train_images,
            "val_images": self.val_images,
        }


def _to_float(text) -> float | None:
    try:
        number = float(text)
    except (TypeError, ValueError):
        return None
    return number if number == number else None


def read_results_csv(path: Path) -> list[EpochPoint]:
    """Read ultralytics' results.csv. Train / val loss = box + cls + dfl loss."""
    if not path.exists():
        return []
    points: list[EpochPoint] = []
    try:
        with open(path, "r", encoding="utf-8", newline="") as handle:
            for index, raw in enumerate(csv.DictReader(handle), start=1):
                row = {(key or "").strip(): value for key, value in raw.items()}

                def total(prefix: str) -> float | None:
                    parts = [_to_float(row.get(f"{prefix}/{kind}_loss")) for kind in ("box", "cls", "dfl")]
                    return sum(p for p in parts if p is not None) if any(p is not None for p in parts) else None

                points.append(EpochPoint(
                    epoch=index,
                    train_loss=total("train"),
                    val_loss=total("val"),
                    map50=_to_float(row.get("metrics/mAP50(B)")),
                ))
    except (OSError, csv.Error):
        return points
    return points


def slugify(text: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9_-]+", "_", text.strip()).strip("_")
    return cleaned[:30]


class RunHistory:
    def __init__(self, root: Path | str = TRAININGS_DIR):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)

    # ---- reading -------------------------------------------------------- #
    def _read(self, folder: Path) -> RunRecord | None:
        meta = folder / "run.json"
        if not meta.exists():
            return None
        try:
            data = json.loads(meta.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return None
        return RunRecord(
            run_id=folder.name, path=folder,
            name=str(data.get("name", "")), created=str(data.get("created", "")),
            model=str(data.get("model", "")), epochs=int(data.get("epochs", 0)),
            batch=int(data.get("batch", 0)), status=str(data.get("status", STATUS_INTERRUPTED)),
            duration_sec=float(data.get("duration_sec", 0.0)),
            classes=list(data.get("classes", [])),
            train_images=int(data.get("train_images", 0)), val_images=int(data.get("val_images", 0)),
        )

    def list_runs(self) -> list[RunRecord]:
        """All trainings, newest first."""
        runs = [r for r in (self._read(f) for f in self.root.iterdir() if f.is_dir()) if r is not None]
        return sorted(runs, key=lambda r: r.run_id, reverse=True)

    def get(self, run_id: str) -> RunRecord | None:
        return self._read(self.root / run_id) if run_id else None

    def usable_runs(self) -> list[RunRecord]:
        """Trainings that have a fine-tuned model (what Step 3 can load)."""
        return [r for r in self.list_runs() if r.has_weights]

    # ---- writing -------------------------------------------------------- #
    def _write(self, record: RunRecord) -> None:
        record.path.mkdir(parents=True, exist_ok=True)
        (record.path / "run.json").write_text(
            json.dumps(record.to_json(), indent=2, ensure_ascii=False), encoding="utf-8")

    def create(self, model: str, epochs: int, batch: int, classes: list[str],
               train_images: int, val_images: int, name: str = "") -> RunRecord:
        """Create the folder of a new training (status 'running')."""
        now = datetime.now()
        label = slugify(name) or f"{Path(model).stem}_e{epochs}"
        run_id = f"{now.strftime('%Y%m%d_%H%M%S')}_{label}"
        counter = 1
        while (self.root / run_id).exists():
            counter += 1
            run_id = f"{now.strftime('%Y%m%d_%H%M%S')}_{label}_{counter}"
        record = RunRecord(
            run_id=run_id, path=self.root / run_id, name=name.strip(),
            created=now.isoformat(timespec="seconds"), model=model, epochs=epochs, batch=batch,
            status=STATUS_RUNNING, classes=list(classes),
            train_images=train_images, val_images=val_images,
        )
        self._write(record)
        return record

    def finish(self, record: RunRecord, status: str, duration_sec: float, log_text: str = "") -> None:
        record.status = status
        record.duration_sec = duration_sec
        self._write(record)
        if log_text:
            record.log_path.write_text(log_text, encoding="utf-8")
        self._tidy(record.path)

    def discard(self, record: RunRecord) -> None:
        """Remove a training that produced nothing (failed before the first epoch)."""
        shutil.rmtree(record.path, ignore_errors=True)

    def delete(self, run_id: str) -> None:
        folder = self.root / run_id
        if not folder.is_dir() or folder.parent != self.root:
            return
        try:
            shutil.rmtree(folder)
        except OSError as error:
            raise HistoryError(
                f"Could not delete '{run_id}': {error}. Close any program that uses its files and try again."
            ) from error

    def mark_interrupted(self) -> None:
        """A training still marked 'running' when the program starts was cut off."""
        for record in self.list_runs():
            if record.status == STATUS_RUNNING:
                record.status = STATUS_INTERRUPTED
                self._write(record)
                self._tidy(record.path)

    @staticmethod
    def _tidy(folder: Path) -> None:
        """Remove files nobody needs: TensorBoard logs and the duplicate last.pt."""
        for pattern in ("events.out.tfevents.*",):
            for file in folder.glob(pattern):
                file.unlink(missing_ok=True)
        (folder / "weights" / "last.pt").unlink(missing_ok=True)
